"""Observability for storing one call recording."""

from __future__ import annotations

from contextlib import contextmanager
from typing import Iterator, Literal, Optional

from opentelemetry import trace
from opentelemetry.trace import Span

from rasa.tracing.voice.shared import semconv
from rasa.tracing.voice.spans import (
    start_voice_span,
    voice_call_context,
    voice_tracing_enabled,
)

RecordingStatus = Literal["available", "failed", "skipped"]


class StoreCallRecordingRecorder:
    """Record the storage outcome for one call recording."""

    def __init__(self, span: Span) -> None:
        self.span = span
        self._status: Optional[RecordingStatus] = None

    @classmethod
    def detached(cls) -> "StoreCallRecordingRecorder":
        """Return a recorder that emits no span."""
        return cls(trace.INVALID_SPAN)

    def record_available(
        self,
        content_type: str,
        *,
        bucket: str,
        key: str,
        uri: str,
    ) -> None:
        """Record that the call recording was stored successfully.

        Args:
            content_type: MIME type of the stored recording.
            bucket: Storage bucket or container. Empty for local files.
            key: Object key or filename of the stored recording.
            uri: Locator for the stored recording (``s3://``, ``gs://``,
                ``https://``, or ``file://``).
        """
        self._status = "available"
        if not self.span.is_recording():
            return
        self.span.set_attribute(semconv.VOICE_RECORDING_CONTENT_TYPE, content_type)
        self.span.set_attribute(semconv.VOICE_RECORDING_BUCKET, bucket)
        self.span.set_attribute(semconv.VOICE_RECORDING_KEY, key)
        self.span.set_attribute(semconv.VOICE_RECORDING_URI, uri)
        self.span.add_event(semconv.EVENT_RECORDING_AVAILABLE)

    def record_failed(self, error: BaseException) -> None:
        """Record that encoding or storing the call recording failed.

        Only ``error.type`` (the exception class name) is exported. The
        exception message and stacktrace stay off the span so SDK or path
        details are not traced.
        """
        self._status = "failed"
        if self.span.is_recording():
            self.span.add_event(semconv.EVENT_RECORDING_FAILED)
            self.span.set_attribute(semconv.ERROR_TYPE, type(error).__name__)
            self.span.set_status(trace.Status(trace.StatusCode.ERROR))

    def record_skipped(self) -> None:
        """Record that no call recording was stored because no audio was captured."""
        self._status = "skipped"
        if self.span.is_recording():
            self.span.add_event(semconv.EVENT_RECORDING_SKIPPED)

    def end(self) -> None:
        """Stamp the terminal recording status and end the span."""
        if self.span.is_recording() and self._status is not None:
            self.span.set_attribute(semconv.VOICE_RECORDING_STATUS, self._status)
        self.span.end()


@contextmanager
def store_call_recording_span(
    *, storage_provider: str, chunk_count: int
) -> Iterator[StoreCallRecordingRecorder]:
    """Open a child span for storing one call recording.

    Args:
        storage_provider: Configured recording storage provider.
        chunk_count: Number of audio chunks captured before finalization.

    Yields:
        Recorder for the storage outcome.
    """
    if not voice_tracing_enabled():
        yield StoreCallRecordingRecorder.detached()
        return

    with voice_call_context():
        recorder = StoreCallRecordingRecorder(
            start_voice_span(
                semconv.SPAN_NAME_STORE_CALL_RECORDING,
                attributes={
                    semconv.VOICE_RECORDING_STORAGE_PROVIDER: storage_provider,
                    semconv.VOICE_RECORDING_CHUNK_COUNT: chunk_count,
                },
            )
        )
        try:
            yield recorder
        except Exception as error:
            recorder.record_failed(error)
            raise
        finally:
            recorder.end()
